#!/usr/bin/env node
/**
 * Wave 10 (and the file-level part of waves 4/5): rename the paths themselves.
 *
 * Path segments are mapped with the *same* token rules the content transformer
 * uses, which is what keeps relative links, `@module` headers, tsconfig
 * `references` and fixture lookups pointing at the renamed target instead of
 * dangling. Renames are done with `git mv` so history follows.
 *
 * Two trees are never touched:
 *  - `.agents/notes/archived/` — content-sealed by verify-archived-agent-notes.
 *  - `snapshots/` — regenerated by the snapshot suite.
 *
 * Usage:
 *   node scripts/rename-brand-paths.mjs [--dry-run] [--verbose]
 *
 * @module scripts/rename-brand-paths
 */

import { execFileSync } from 'node:child_process'
import { mkdirSync } from 'node:fs'
import { dirname } from 'node:path'

/** Segment-level rules, ordered longest/most-specific first. */
const SEGMENT_RULES = [
  { from: /--dsh-/g, to: '--avn-' },
  { from: /^dsh-/g, to: 'avn-' },
  { from: /-dsh-/g, to: '-avn-' },
  { from: /(?<![A-Za-z0-9])dsh(?![A-Za-z0-9])/g, to: 'avn' },
  { from: /(?<![A-Za-z0-9])Dsh(?=[A-Z0-9])/g, to: 'Avn' },
  { from: /(?<=[a-z0-9])Dsh(?=[A-Z0-9])/g, to: 'Avn' },
  { from: /^dsh\./g, to: 'avn.' },
  { from: /^dsh(?=[A-Z0-9])/g, to: 'avn' },
]

/**
 * Map one path segment.
 * @param segment - a single path component.
 * @returns the renamed component, or the original when nothing matched.
 */
function mapSegment(segment) {
  let next = segment
  for (const rule of SEGMENT_RULES) {
    rule.from.lastIndex = 0
    next = next.replace(rule.from, rule.to)
  }
  return next
}

/**
 * Whether a path is inside a tree that must never be renamed.
 * @param path - repository-relative path.
 * @returns true when the path is frozen.
 */
function frozen(path) {
  return path.startsWith('.agents/notes/archived/') || path.startsWith('snapshots/')
}

function main() {
  const dryRun = process.argv.includes('--dry-run')
  const verbose = process.argv.includes('--verbose')

  const paths = execFileSync('git', ['ls-files'], { encoding: 'utf8' })
    .split('\n').filter(Boolean).filter((p) => !frozen(p))

  // Deepest first, so a child rename never invalidates a queued parent path.
  const movers = []
  for (const path of paths) {
    const mapped = path.split('/').map(mapSegment).join('/')
    if (mapped !== path) movers.push([path, mapped])
  }
  movers.sort((a, b) => b[0].length - a[0].length)

  let moved = 0
  for (const [from, to] of movers) {
    if (verbose) console.log(`  ${from}\n    -> ${to}`)
    if (!dryRun) {
      mkdirSync(dirname(to), { recursive: true })
      execFileSync('git', ['mv', from, to])
    }
    moved += 1
  }
  console.log(`${dryRun ? '(dry run) ' : ''}renamed ${moved} paths`)
}

main()
